@cached_property
def _unwrapped_calls(self) -> List[Any]:
    """
    All the callables in the wrapping chain (functools.wraps via
    `__wrapped__`, and functools.partial via `.func`), outermost first.
    """
    if self.call is None:
        return []  # pragma: no cover
    chain: List[Any] = []
    current: Any = self.call
    seen: set = set()
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        chain.append(current)
        if isinstance(current, partial):
            current = current.func
        elif hasattr(current, "__wrapped__"):
            current = current.__wrapped__
        else:
            break
    return chain

@cached_property
def _unwrapped_call(self) -> Any:
    return self._unwrapped_calls[-1] if self._unwrapped_calls else self.call

def _level_matches(self, obj: Any, check: Callable[[Any], bool]) -> bool:
    if inspect.isroutine(obj):
        return check(obj)
    if inspect.isclass(obj):
        return False
    dunder_call = getattr(obj, "__call__", None)  # noqa: B004
    return dunder_call is not None and check(dunder_call)

@cached_property
def is_gen_callable(self) -> bool:
    return any(
        self._level_matches(obj, inspect.isgeneratorfunction)
        for obj in self._unwrapped_calls
    )

@cached_property
def is_async_gen_callable(self) -> bool:
    return any(
        self._level_matches(obj, inspect.isasyncgenfunction)
        for obj in self._unwrapped_calls
    )

@cached_property
def is_coroutine_callable(self) -> bool:
    return any(
        self._level_matches(obj, iscoroutinefunction)
        for obj in self._unwrapped_calls
    )

