import functools
from fastapi import FastAPI
from fastapi.testclient import TestClient
from pydantic import BaseModel
def deco(f):
    @functools.wraps(f)
    def w(*a, **k): return f(*a, **k)
    return w
class Item(BaseModel):
    name: str
app = FastAPI()
@app.post('/')
@deco
def h(item: 'Item'):
    return item
print(TestClient(app).post('/', json={'name':'x'}).json())
